from google.cloud import translate_v3
from google.cloud.translate_v3 import types
from vision_client import get_google_translation_client
from vision_models import TranslatedText

def translate_alt_text(text: str, target_language_code: str, source_language_code: str = "en") -> TranslatedText:
    client = get_google_translation_client()

    project_id = os.environ.get("GOOGLE_CLOUD_PROJECT")
    if not project_id:
        raise ValueError("GOOGLE_CLOUD_PROJECT environment variable must be set for Google Cloud Translation.")

    parent = f"projects/{project_id}/locations/global"

    response = client.translate_text(
        parent=parent,
        contents=[text],
        target_language_code=target_language_code,
        source_language_code=source_language_code,
    )

    if response.translations:
        translation = response.translations[0]
        return TranslatedText(text=translation.translated_text, language_code=target_language_code)
    else:
        raise Exception("Translation failed or returned no results.")",
  "visual_safety_text.py": "import os
from openai import OpenAI
from typing import List
from vision_client import get_openai_client
from vision_models import ModerationResult

def check_text_safety(texts: List[str]) -> List[ModerationResult]:
    client = get_openai_client()

    moderation_results = []
    for text in texts:
        response = client.moderations.create(input=text, model="text-moderation-latest")

        result = response.results[0]
        moderation_results.append(
            ModerationResult(
                flagged=result.flagged,
                categories={k: getattr(result.categories, k) for k in result.categories.__dict__ if not k.startswith('_')},
                category_scores={k: getattr(result.category_scores, k) for k in result.category_scores.__dict__ if not k.startswith('_')}
            )
        )
    return moderation_results",
